#!/bin/bash
# usage: post.sh <name> <issue_number>   posts s12/<name>.md + footer to main#<issue>, reads back, compares
set -euo pipefail
D=<SCRATCH>/s18
n=$1; iss=$2
[ -e "$D/${n}_posted.txt" ] && { echo "STOP: already posted $(cat $D/${n}_posted.txt)"; exit 2; }
printf '%s\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n' "$(cat "$D/$n.md")" > "$D/${n}_full.md"
grep -qE 'RESULT_ID|CONTENDER_(TIME|TEXT)' "$D/${n}_full.md" && { echo "STOP: placeholder"; exit 2; }
grep -qE 'Math-#[0-9]' "$D/${n}_full.md" && { echo "STOP: cross-repo autolink"; exit 2; }
grep -qiE "chatgpt|gpt-?[0-9]|grok ?[0-9]|\bopus\b|sonnet|haiku|fable|okcomputer" "$D/${n}_full.md" && { echo "STOP: model or product name"; exit 2; }
grep -qE "\bKimi\b" "$D/${n}_full.md" && { echo "STOP: bare product name"; exit 2; }
grep -qiE '(close[sd]?|fix(e[sd])?|resolve[sd]?) +#[0-9]' "$D/${n}_full.md" && { echo "STOP: closing verb"; exit 2; }
python3 -c "import re,sys;s=open(sys.argv[1]).read();bad=[t for t in re.findall(r'[A-Za-z0-9_-]{25,}',s) if re.search(r'[a-z]',t) and re.search(r'[A-Z]',t) and re.search(r'[0-9]',t) and 'session_' not in t and t!='01Cz7WZybv8znP64SpPj6sWY'];bad+=re.findall(r'(?:drive|docs)\\.google',s);sys.exit(1 if bad else 0)" "$D/${n}_full.md" || { echo "STOP: drive-like id"; exit 2; }
out=$(gh api "repos/d6g8k5htny-coder/main/issues/$iss/comments" -F body=@"$D/${n}_full.md" --jq '[.id, .created_at]|@tsv')
echo "$out" > "$D/${n}_posted.txt"; id=$(cut -f1 <<<"$out"); echo "posted $out"
gh api "repos/d6g8k5htny-coder/main/issues/comments/$id" --jq .body > "$D/${n}_readback.md"
strip() { python3 -c "import sys,re;s=open(sys.argv[1]).read();s=re.sub(r'\s*---\s*_Generated by \[Claude Code\]\(https://claude\.ai/code\)_\s*\$','',s.rstrip());print(s.rstrip())" "$1"; }
if diff <(strip "$D/${n}_full.md") <(strip "$D/${n}_readback.md") >/dev/null; then echo "READBACK MATCH ($id)"; else echo "READBACK DIFF"; diff <(strip "$D/${n}_full.md") <(strip "$D/${n}_readback.md") | head; exit 3; fi
